        {
          "source": "alerts.jsonl",
          "line": 2,
          "quote": "\"ts\":\"2026-03-17T09:31:00.000Z\",\"name\":\"ApiLatencyP95\",\"severity\":\"ticket\",\"state\":\"firing\""
        }
      ]
    },
    {
      "statement": "Repeated errors of TypeError: Cannot read properties of null (reading 'percentOff') in the applyDiscount handler started at 09:23:01 and continued throughout the incident.",
      "citations": [
        {
          "source": "logs/app.jsonl",
          "line": 645,
          "quote": "\"ts\":\"2026-03-17T09:23:01.000Z\",\"service\":\"checkout\",\"level\":\"error\",\"msg\":\"TypeError: Cannot read properties of null (reading 'percentOff')\",\"handler\":\"applyDiscount\",\"release\":\"v2026.3.17-a1\""
