        {
          "source": "logs/app.jsonl",
          "line": 645,
          "quote": "\"msg\":\"TypeError: Cannot read properties of null (reading 'percentOff')\",\"handler\":\"applyDiscount\",\"release\":\"v2026.3.17-a1\""
        }
      ]
    },
    {
      "statement": "The incident onset closely follows the deployment of the new tiered discount support, linking the regression to this change.",
      "citations": [
        {
          "source": "changes.jsonl",
